import sqlite3
con = sqlite3.connect(':memory:')
con.executescript('''
CREATE TABLE t(k TEXT PRIMARY KEY, v);
CREATE TABLE events(kind, old_v, new_v);
CREATE TRIGGER before_change BEFORE UPDATE ON t WHEN OLD.v=78 AND NEW.v=77 BEGIN UPDATE t SET v=77 WHERE k=OLD.k; END;
CREATE TRIGGER after_change AFTER UPDATE ON t BEGIN INSERT INTO events VALUES ('main', OLD.v, NEW.v); END;
CREATE TEMP TRIGGER observe AFTER UPDATE ON main.t BEGIN INSERT INTO events VALUES ('temp', OLD.v, NEW.v); END;
INSERT INTO t VALUES ('x',77);
UPDATE t SET v=78; UPDATE t SET v=77; UPDATE t SET v=78;
''')
print('Observer order and stale OLD:', con.execute('SELECT * FROM events').fetchall())
con.executescript('''CREATE TEMP TRIGGER observe_delete AFTER DELETE ON main.t BEGIN INSERT INTO events VALUES ('delete', OLD.v, NULL); END; PRAGMA recursive_triggers=ON; INSERT OR REPLACE INTO t VALUES ('x',79);''')
print('REPLACE observed:', con.execute(\"SELECT * FROM events WHERE kind='delete'\").fetchall())
for source in (\"'pragma_recursive_triggers'()\", 'main.pragma_recursive_triggers()', 'temp.pragma_recursive_triggers()', 'pragma_recursive_triggers'):
    try:
        print(source, con.execute('SELECT * FROM ' + source).fetchall())
    except sqlite3.Error as exc:
        print(source, type(exc).__name__)
for name in ('begin', 'end', 'λ', 'dollar"'$name'"', '\\ufeffedge', 'a\\ufeffb', 'a\\u00a0b'):
    try:
        con.execute('CREATE TRIGGER ' + name + ' AFTER INSERT ON t BEGIN SELECT 1; END')
        print('native trigger:', repr(name), 'accepted')
    except sqlite3.Error as exc:
        print('native trigger:', repr(name), type(exc).__name__)
for separator in ('\\v', '\\ufeff', '\\u00a0'):
    try:
        con.execute('CREATE TRIGGER ' + 's' + str(ord(separator)) + ' AFTER INSERT ON t BEGIN SELECT' + separator + '1; END')
        print('native separator:', repr(separator), 'accepted')
    except sqlite3.Error as exc:
        print('native separator:', repr(separator), type(exc).__name__)
