from test_integrity import WriteIntegrityRegressions
case = WriteIntegrityRegressions()
checks = {
 'cte-shadow': '''CREATE VIEW saved_mode AS WITH pragma_recursive_triggers(recursive_triggers) AS (VALUES(7)) SELECT * FROM pragma_recursive_triggers; CREATE TRIGGER guard BEFORE INSERT ON audit WHEN (SELECT recursive_triggers FROM saved_mode)<>7 BEGIN SELECT RAISE(ABORT,'shadowed CTE'); END;''',
 'schema-column': '''CREATE VIEW saved_mode AS SELECT main.pragma_recursive_triggers.recursive_triggers FROM main.pragma_recursive_triggers(); CREATE TRIGGER guard BEFORE INSERT ON audit WHEN (SELECT recursive_triggers FROM saved_mode)<>0 BEGIN SELECT RAISE(ABORT,'schema column'); END;''',
 'unchanged-column-before': '''CREATE TRIGGER mutate_name BEFORE UPDATE ON accounts WHEN OLD.tenant='blue' AND OLD.name='private' BEGIN UPDATE accounts SET name='changed' WHERE rowid=OLD.rowid; END; CREATE TRIGGER body AFTER INSERT ON audit BEGIN UPDATE accounts SET balance=77 WHERE tenant='blue' AND name='private'; END;''',
}
try:
    for name, setup in checks.items():
        try:
            if name == 'unchanged-column-before':
                case.assert_rollback(setup)
            else:
                case.assert_native_control(setup)
            print(name, 'PASS')
        except Exception as exc:
            print(name, type(exc).__name__, str(exc))
finally:
    case.doCleanups()
